```json
{
  "root_causes": [
    {
      "service": "reservation",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'reservation%' AND metric IN ('k8s.container.restarts','k8s.container.ready') ORDER BY time",
          "claim": "Reservation pod restart count climbs from 2 to 6 and container is not ready throughout the abnormal window"
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name = 'reservation' OR span_name LIKE 'reservation.Reservation/%' GROUP BY ALL ORDER BY 1,2,3,4",
          "claim": "Reservation emits no server spans in the abnormal window, while frontend's reservation client calls all return Error"
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, message, count(*) n FROM abnormal_logs WHERE level='ERROR' GROUP BY 1,2 ORDER BY n DESC",
          "claim": "Frontend logs 'Reservation check availability failed' about 291 times; reservation itself logs nothing in the abnormal window"
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH h AS (SELECT trace_id, span_id, attr_status_code st FROM abnormal_traces WHERE span_name='HTTP /hotels' AND service_name='frontend') SELECT t.service_name, t.span_name, t.attr_span_kind, t.attr_status_code child_st, h.st parent_st, count(*) n, round(median(t.duration)/1e6,2) med_ms FROM abnormal_traces t JOIN h ON t.trace_id=h.trace_id WHERE t.span_id<>h.span_id GROUP BY ALL ORDER BY 1,2,4",
          "claim": "Failing frontend /hotels requests (HTTP 500) all have a child reservation CheckAvailability client span with Error status in about 0.01 ms"
        }
      ]
    }
  ]
}
```

